function getRegistryForDate(PDO $db, string $date): array {
    $stmt = $db->prepare("SELECT * FROM registry WHERE date = ? ORDER BY type, id");
    $stmt->execute([$date]);
    return $stmt->fetchAll();
}
function getRegistryForRange(PDO $db, string $from, string $to): array {
    $stmt = $db->prepare("SELECT * FROM registry WHERE date BETWEEN ? AND ? ORDER BY date, type, id");
    $stmt->execute([$from, $to]);
    return $stmt->fetchAll();
}
function getRegistryNumberForDate(PDO $db, string $date): ?array {
    $stmt = $db->prepare("SELECT registry_number, print_date, frozen
                          FROM registry
                          WHERE date = ? AND registry_number > 0
                          LIMIT 1");
    $stmt->execute([$date]);
    $row = $stmt->fetch();
    return $row ?: null;
}

function assignRegistryNumber(PDO $db, array $dates): array {
    $lockName = 'registry_assign_lock';
    $stmtLock = $db->prepare("SELECT GET_LOCK(?, 10)");
    $stmtLock->execute([$lockName]);
    $got = (int)$stmtLock->fetchColumn();
    if ($got !== 1) {
        return ['success' => false, 'message' => 'Р В Р’В Р вЂ™Р’В Р В Р Р‹Р РЋРЎв„ўР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’Вµ Р В Р’В Р В Р вЂ№Р В Р Р‹Р Р†Р вЂљРЎС™Р В Р’В Р вЂ™Р’В Р В РЎС›Р Р†Р вЂљР’ВР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В°Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В»Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎС›Р В Р’В Р В Р вЂ№Р В Р’В Р РЋРІР‚СљР В Р’В Р В Р вЂ№Р В Р’В Р В РІР‚В° Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРІР‚СњР В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎС›Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В»Р В Р’В Р В Р вЂ№Р В Р Р‹Р Р†Р вЂљРЎС™Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р В Р вЂ№Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљР’ВР В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРІвЂћСћР В Р’В Р В Р вЂ№Р В Р’В Р В РІР‚В° Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В±Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В»Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎС›Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎСљР В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљР’ВР В Р’В Р В Р вЂ№Р В Р’В Р Р†Р вЂљРЎв„ўР В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎС›Р В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎСљР В Р’В Р В Р вЂ№Р В Р Р‹Р Р†Р вЂљРЎС™. Р В Р’В Р вЂ™Р’В Р В Р Р‹Р РЋРЎСџР В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎС›Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРІР‚СњР В Р’В Р В Р вЂ№Р В Р’В Р Р†Р вЂљРЎв„ўР В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎС›Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В±Р В Р’В Р В Р вЂ№Р В Р Р‹Р Р†Р вЂљРЎС™Р В Р’В Р вЂ™Р’В Р В Р вЂ Р Р†Р вЂљРЎвЂєР Р†Р вЂљРІР‚СљР В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРІвЂћСћР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’Вµ Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’ВµР В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р вЂ™Р’В°Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р’В Р Р†Р вЂљРЎв„ўР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В°Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В·.'];
    }

    try {
        $db->beginTransaction();

        $occupied = [];
        foreach ($dates as $date) {
            $existing = getRegistryNumberForDate($db, $date);
            if ($existing) $occupied[$date] = (int)$existing['registry_number'];
        }
        if (!empty($occupied)) {
            $db->rollBack();
            return ['success' => false, 'occupied' => $occupied];
        }

        $stmt = $db->query("SELECT MAX(registry_number) AS max_num FROM registry FOR UPDATE");
        $max = (int)($stmt->fetch()['max_num'] ?? 0);
        $registry_number = $max + 1;
        $print_date = date('d.m.y');

        $stmtUp = $db->prepare("UPDATE registry SET registry_number = ?, print_date = ? WHERE date = ?");
        $updatedTotal = 0;
        foreach ($dates as $date) {
            $stmtUp->execute([$registry_number, $print_date, $date]);
            $updatedTotal += $stmtUp->rowCount();
        }
        if ($updatedTotal === 0) {
            $db->rollBack();
            return ['success' => false, 'message' => 'Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р Р†РІР‚С›РЎС› Р В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р Р†РІР‚С›РІР‚вЂњР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В±Р В Р’В Р В Р вЂ№Р В Р’В Р Р†Р вЂљРЎв„ўР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В°Р В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В¦Р В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В¦Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎС›Р В Р’В Р вЂ™Р’В Р В Р Р‹Р вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРІР‚СњР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’ВµР В Р’В Р В Р вЂ№Р В Р’В Р Р†Р вЂљРЎв„ўР В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљР’ВР В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎС›Р В Р’В Р вЂ™Р’В Р В РЎС›Р Р†Р вЂљР’ВР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’Вµ Р В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В¦Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’ВµР В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРІвЂћСћ Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В·Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В°Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРІР‚СњР В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљР’ВР В Р’В Р В Р вЂ№Р В Р’В Р РЋРІР‚СљР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’ВµР В Р’В Р вЂ™Р’В Р В Р вЂ Р Р†Р вЂљРЎвЂєР Р†Р вЂљРІР‚Сљ. Р В Р’В Р вЂ™Р’В Р В Р Р‹Р РЋРЎСџР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’ВµР В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р В Р вЂ№Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В°Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРІвЂћСћР В Р’В Р В Р вЂ№Р В Р’В Р В РІР‚В° Р В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В¦Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’ВµР В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎС›Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В·Р В Р’В Р вЂ™Р’В Р В Р Р‹Р вЂ™Р’ВР В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎС›Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В¶Р В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В¦Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В°.'];
        }

        $db->commit();
        return ['success' => true, 'registry_number' => $registry_number, 'print_date' => $print_date];
    } catch (Throwable $e) {
        if ($db->inTransaction()) $db->rollBack();
        return ['success' => false, 'message' => 'Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎвЂќР В Р’В Р В Р вЂ№Р В Р вЂ Р Р†Р вЂљРЎв„ўР вЂ™Р’В¬Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљР’ВР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В±Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎСљР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В° Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРІР‚СњР В Р’В Р В Р вЂ№Р В Р’В Р Р†Р вЂљРЎв„ўР В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљР’ВР В Р’В Р В Р вЂ№Р В Р’В Р РЋРІР‚СљР В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎС›Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’ВµР В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В¦Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљР’ВР В Р’В Р В Р вЂ№Р В Р’В Р В Р РЏ Р В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В¦Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎС›Р В Р’В Р вЂ™Р’В Р В Р Р‹Р вЂ™Р’ВР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’ВµР В Р’В Р В Р вЂ№Р В Р’В Р Р†Р вЂљРЎв„ўР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В°: ' . $e->getMessage()];
    } finally {
        $stmtUnlock = $db->prepare("SELECT RELEASE_LOCK(?)");
        $stmtUnlock->execute([$lockName]);
    }
}

function clearRegistryNumber(PDO $db, int $registry_number): void {
    $stmt = $db->prepare("UPDATE registry SET registry_number = 0, print_date = '', frozen = 0 WHERE registry_number = ?");
    $stmt->execute([$registry_number]);
}
function freezeReestr(PDO $db, int $registry_number): void {
    $stmt = $db->prepare("UPDATE registry SET frozen = 1 WHERE registry_number = ?");
    $stmt->execute([$registry_number]);
}
function unfreezeReestr(PDO $db, int $registry_number): void {
    $stmt = $db->prepare("UPDATE registry SET frozen = 0 WHERE registry_number = ?");
    $stmt->execute([$registry_number]);
}

function getReestrsList(PDO $db): array {
    $stmt = $db->query("SELECT registry_number, print_date,
                               GROUP_CONCAT(DISTINCT date) as dates,
                               COUNT(*) as count,
                               MAX(frozen) AS is_frozen
                        FROM registry
                        WHERE registry_number > 0
                        GROUP BY registry_number
                        ORDER BY registry_number DESC");
    return $stmt->fetchAll();
}

function deleteFromRegistry(PDO $db, int $id): bool {
    $stmt = $db->prepare("SELECT date FROM registry WHERE id = ?");
    $stmt->execute([$id]);
    $date = (string)($stmt->fetchColumn() ?? '');
    if ($date && isDayFrozen($db, $date)) return false;

    $stmt = $db->prepare("DELETE FROM registry WHERE id = ?");
    $stmt->execute([$id]);
    return true;
}

/* =======================
   SCANS STORAGE
======================= */
function ensureScansTable(PDO $db): bool {
    try {
        $db->exec("
            CREATE TABLE IF NOT EXISTS registry_scans (
                id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
                registry_id INT NOT NULL,
                original_name VARCHAR(255) NOT NULL,
                stored_name VARCHAR(255) NOT NULL,
                relative_path VARCHAR(500) NOT NULL,
                mime_type VARCHAR(120) NOT NULL,
                file_size BIGINT UNSIGNED NOT NULL DEFAULT 0,
                uploaded_by_role VARCHAR(32) NOT NULL DEFAULT '',
                created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                INDEX idx_registry_id (registry_id)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
        ");
        return true;
    } catch (Throwable $e) {
        return false;
    }
}

function scansAllowedExts(): array {
    return ['pdf', 'jpg', 'jpeg', 'png', 'tif', 'tiff'];
}

function scansAllowedMime(): array {
    return [
        'application/pdf',
        'image/jpeg',
        'image/png',
        'image/tiff',
    ];
}

function scansStorageRoot(): string {
    return rtrim((string)SCANS_STORAGE_PATH, "\\/");
}

function getRegistryRowById(PDO $db, int $id): ?array {
    $stmt = $db->prepare("SELECT * FROM registry WHERE id = ?");
    $stmt->execute([$id]);
    $row = $stmt->fetch();
    return $row ?: null;
}

function getScansForRegistryIds(PDO $db, array $registryIds): array {
    if (empty($registryIds)) return [];
    $registryIds = array_values(array_unique(array_map('intval', $registryIds)));
    $in = implode(',', array_fill(0, count($registryIds), '?'));
    $stmt = $db->prepare("SELECT * FROM registry_scans WHERE registry_id IN ($in) ORDER BY created_at DESC, id DESC");
    $stmt->execute($registryIds);

    $map = [];
    foreach ($stmt->fetchAll() as $row) {
        $rid = (int)$row['registry_id'];
        if (!isset($map[$rid])) $map[$rid] = [];
        $map[$rid][] = $row;
    }
    return $map;
}

function saveRegistryScan(PDO $db, int $registryId, array $file, string $role): array {
    $doc = getRegistryRowById($db, $registryId);
    if (!$doc) return ['success' => false, 'message' => 'Registry row not found'];

    if (($file['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK) {
        return ['success' => false, 'message' => 'Upload failed'];
    }

    $tmp = (string)($file['tmp_name'] ?? '');
    $orig = trim((string)($file['name'] ?? ''));
    $size = (int)($file['size'] ?? 0);
    if ($tmp === '' || $orig === '') return ['success' => false, 'message' => 'File is missing'];
    if ($size <= 0) return ['success' => false, 'message' => 'File is empty'];
    if ($size > (int)SCANS_MAX_FILE_SIZE) return ['success' => false, 'message' => 'File is too large (max 25MB)'];

    $ext = strtolower(pathinfo($orig, PATHINFO_EXTENSION));
    if (!in_array($ext, scansAllowedExts(), true)) {
        return ['success' => false, 'message' => 'Unsupported file extension'];
    }

    $finfo = new finfo(FILEINFO_MIME_TYPE);
    $mime = (string)$finfo->file($tmp);
    if (!in_array($mime, scansAllowedMime(), true)) {
        return ['success' => false, 'message' => 'Unsupported file type (MIME)'];
    }

    $root = scansStorageRoot();
    if (!is_dir($root) && !mkdir($root, 0775, true) && !is_dir($root)) {
        return ['success' => false, 'message' => 'Cannot create scans root directory'];
    }

    $docDirRel = (string)$registryId;
    $docDir = $root . DIRECTORY_SEPARATOR . $docDirRel;
    if (!is_dir($docDir) && !mkdir($docDir, 0775, true) && !is_dir($docDir)) {
        return ['success' => false, 'message' => 'Cannot create document scan directory'];
    }

    $stored = bin2hex(random_bytes(12)) . '.' . $ext;
    $relative = $docDirRel . '/' . $stored;
    $target = $docDir . DIRECTORY_SEPARATOR . $stored;

    if (!move_uploaded_file($tmp, $target)) {
        return ['success' => false, 'message' => 'Cannot move uploaded file'];
    }

    $stmt = $db->prepare("INSERT INTO registry_scans
        (registry_id, original_name, stored_name, relative_path, mime_type, file_size, uploaded_by_role)
        VALUES (?, ?, ?, ?, ?, ?, ?)");
    $stmt->execute([$registryId, $orig, $stored, $relative, $mime, $size, $role]);

    return ['success' => true, 'message' => 'Scan uploaded'];
}

function deleteRegistryScan(PDO $db, int $scanId): array {
    $stmt = $db->prepare("SELECT * FROM registry_scans WHERE id = ?");
    $stmt->execute([$scanId]);
    $row = $stmt->fetch();
    if (!$row) return ['success' => false, 'message' => 'Scan not found'];

    $path = scansStorageRoot() . DIRECTORY_SEPARATOR . str_replace(['/', '\\'], DIRECTORY_SEPARATOR, (string)$row['relative_path']);
    if (is_file($path) && !@unlink($path)) {
        return ['success' => false, 'message' => 'Cannot delete file from storage'];
    }

    $del = $db->prepare("DELETE FROM registry_scans WHERE id = ?");
    $del->execute([$scanId]);
    return ['success' => true, 'message' => 'Scan deleted'];
}

function getRegistryScanById(PDO $db, int $scanId): ?array {
    $stmt = $db->prepare("SELECT * FROM registry_scans WHERE id = ?");
    $stmt->execute([$scanId]);
    $row = $stmt->fetch();
    return $row ?: null;
}

