if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = $_POST['action'] ?? '';

    if ($action === 'login') {
        require_csrf();
        $pass = (string)($_POST['credential'] ?? '');

        $matchedRole = '';
        foreach (AUTH_ROLE_PASSWORDS as $role => $rolePass) {
            if (hash_equals((string)$rolePass, $pass)) {
                $matchedRole = (string)$role;
                break;
            }
        }

        if ($matchedRole !== '') {
            session_regenerate_id(true);
            $_SESSION['role'] = $matchedRole;
        } else {
            set_alert('Р В Р’В Р вЂ™Р’В Р В Р Р‹Р РЋРЎв„ўР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’ВµР В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’ВµР В Р’В Р В Р вЂ№Р В Р’В Р Р†Р вЂљРЎв„ўР В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В¦Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р Р†РІР‚С›РІР‚вЂњР В Р’В Р вЂ™Р’В Р В Р вЂ Р Р†Р вЂљРЎвЂєР Р†Р вЂљРІР‚Сљ Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРІР‚СњР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В°Р В Р’В Р В Р вЂ№Р В Р’В Р Р†Р вЂљРЎв„ўР В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎС›Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В»Р В Р’В Р В Р вЂ№Р В Р’В Р В РІР‚В°');
        }
        header('Location: ' . $_SERVER['PHP_SELF']);
        exit;
    }

    if (!$isAuthenticated) { http_response_code(403); die('Forbidden'); }

    if ($action === 'upload_scan') {
        require_csrf();
        header('Content-Type: application/json; charset=utf-8');
        if (!$scansReady) {
            http_response_code(503);
            echo json_encode(['success' => false, 'message' => 'Scans storage is unavailable'], JSON_UNESCAPED_UNICODE);
            exit;
        }
        if (!$canUploadScans) {
            http_response_code(403);
            echo json_encode(['success' => false, 'message' => 'Недостаточно прав'], JSON_UNESCAPED_UNICODE);
            exit;
        }

        $docId = (int)($_POST['doc_id'] ?? 0);
        if ($docId <= 0) {
            echo json_encode(['success' => false, 'message' => 'Неверный id записи'], JSON_UNESCAPED_UNICODE);
            exit;
